		Version          string
		Release          string
		NewVersion       string
		NewRelease       string
		Arch             string
		Repository       string
		Changelog        Changelog
		AffectedProcs    []AffectedProcess
		NeedRestartProcs []NeedRestartProcess
	}
	type args struct {
		stat PackageFixStatus
	}
	tests := []struct {
		name   string
		fields fields
		args   args
		want   string
	}{
