// Changelog has contents of changelog and how to get it.
// Method: models.detectionMethodStr
type Changelog struct {
	Contents string          `json:"contents"`
	Method   DetectionMethod `json:"method"`
}

// AffectedProcess keep a processes information affected by software update
type AffectedProcess struct {
	PID             string     `json:"pid,omitempty"`
	Name            string     `json:"name,omitempty"`
	ListenPorts     []string   `json:"listenPorts,omitempty"`
	ListenPortStats []PortStat `json:"listenPortStats,omitempty"`
}

// PortStat has the result of parsing the port information to the address and port.
type PortStat struct {
	BindAddress     string   `json:"bindAddress"`
	Port            string   `json:"port"`
	PortReachableTo []string `json:"portReachableTo"`
}

// NewPortStat parses an IP address and port from a listening socket address.
func NewPortStat(ipPort string) (*PortStat, error) {
	stat := &PortStat{}
	if ipPort == "" {
		return stat, nil
	}

	host, port, err := net.SplitHostPort(ipPort)
	if err != nil || host == "" || port == "" || (host != "*" && net.ParseIP(host) == nil) {
		return nil, xerrors.Errorf("Invalid listening port: %s", ipPort)
	}
	portNumber, err := strconv.Atoi(port)
	if err != nil || portNumber < 0 || portNumber > 65535 {
		return nil, xerrors.Errorf("Invalid listening port: %s", ipPort)
	}
	if strings.Contains(host, ":") {
		host = "[" + host + "]"
	}
	stat.BindAddress = host
	stat.Port = port
	return stat, nil
}

// HasReachablePort checks if any affected process has a reachable port.
func (p Package) HasReachablePort() bool {
	for _, ap := range p.AffectedProcs {
		for _, stat := range ap.ListenPortStats {
			if len(stat.PortReachableTo) > 0 {
				return true
			}
		}
	}

	return false
}

// NeedRestartProcess keep a processes information affected by software update
type NeedRestartProcess struct {
	PID         string `json:"pid"`
	Path        string `json:"path"`
	ServiceName string `json:"serviceName"`
	InitSystem  string `json:"initSystem"`
	HasInit     bool   `json:"-"`
}

